    adds r5,r0,#0x0    @ 0806569a 051c
    adds r4,r1,#0x0    @ 0806569c 0c1c
    cmp r4,#0x0                              @ 0806569e 002c
    beq LAB_080656d6                         @ 080656a0 19d0
    movs r0,#0x2    @ 080656a2 0220
    ldrb r1,[r4,#0x4]                        @ 080656a4 2179
    orrs r0,r1    @ 080656a6 0843
    movs r1,#0x4    @ 080656a8 0421
    orrs r0,r1    @ 080656aa 0843
    movs r1,#0x8    @ 080656ac 0821
    orrs r0,r1    @ 080656ae 0843
    strb r0,[r4,#0x4]                        @ 080656b0 2071
    ldrb r1,[r4,#0x2]                        @ 080656b2 a178
    lsls r0,r1,#0x1f    @ 080656b4 c807
    lsrs r0,r0,#0x1f    @ 080656b6 c00f
    lsls r1,r1,#0x1a    @ 080656b8 8906
    lsrs r1,r1,#0x1b    @ 080656ba c90e
    ldrh r3,[r4,#0x4]                        @ 080656bc a388
    lsls r2,r3,#0x11    @ 080656be 5a04
    lsrs r2,r2,#0x17    @ 080656c0 d20d
    bl enqueue_field_slot_sprite_with_state_update @ 080656c2 dff783fb
    ldrb r2,[r4,#0x2]                        @ 080656c6 a278
    lsls r1,r2,#0x1f    @ 080656c8 d107
    lsrs r1,r1,#0x1f    @ 080656ca c90f
    lsls r2,r2,#0x1a    @ 080656cc 9206
    lsrs r2,r2,#0x1b    @ 080656ce d20e
    adds r0,r5,#0x0    @ 080656d0 281c
